const input = $('Normalize Input').first().json;
function safeAll(name) { try { return $(name).all().map(i => i.json); } catch (e) { return []; } }
function num(v) { return Number(v) || 0; }
const newsItems = safeAll('Fetch Google News').filter(j => j && j.title).slice(0, 25).map(j => ({ title: j.title, link: j.link || '', date: j.pubDate || j.isoDate || '' }));
const redditJson = safeAll('Fetch Reddit Discussions')[0] || {};
const redditPosts = ((redditJson.data && redditJson.data.children) || []).map(c => c.data).filter(Boolean).slice(0, 20).map(p => ({ source: 'Reddit r/' + p.subreddit, title: p.title, engagement: (p.score || 0) + ' upvotes, ' + (p.num_comments || 0) + ' comments', link: 'https://www.reddit.com' + (p.permalink || '') }));
const hnJson = safeAll('Fetch Hacker News')[0] || {};
const hnPosts = (hnJson.hits || []).filter(h => h.title).slice(0, 15).map(h => ({ source: 'Hacker News', title: h.title, engagement: (h.points || 0) + ' points', link: h.url || ('https://news.ycombinator.com/item?id=' + h.objectID) }));
const socialItems = redditPosts.concat(hnPosts);
const tiktokVideos = safeAll('Fetch TikTok Videos').filter(v => v && !v.error && (v.webVideoUrl || v.text)).map(v => ({ text: String(v.text || '').slice(0, 200), views: num(v.playCount), likes: num(v.diggCount), shares: num(v.shareCount), comments: num(v.commentCount), author: (v.authorMeta && (v.authorMeta.name || v.authorMeta.nickName)) || '', hashtags: (v.hashtags || []).map(h => (h && h.name) || h).filter(x => typeof x === 'string' && x).slice(0, 6), date: v.createTimeISO || '', link: v.webVideoUrl || '' })).sort((a, b) => b.views - a.views).slice(0, 20);
const tiktokComments = safeAll('Fetch TikTok Comments').filter(c => c && !c.error && c.text).sort((a, b) => num(b.diggCount) - num(a.diggCount)).slice(0, 40).map(c => ({ text: String(c.text).slice(0, 200), likes: num(c.diggCount), link: c.videoWebUrl || '' }));
const fbPosts = safeAll('Fetch Facebook Page Posts').filter(p => p && !p.error && (p.text || p.url)).slice(0, 25).map(p => ({ page: p.pageName || (p.user && p.user.name) || '', text: String(p.text || '').slice(0, 250), likes: num(p.likes || p.reactionsCount), comments: num(p.comments || p.commentsCount), shares: num(p.shares || p.sharesCount), date: p.time || '', link: p.url || p.topLevelUrl || '' }));
const fbAds = safeAll('Fetch Facebook Ads').filter(a => a && !a.error && (a.pageName || a.page_name || a.snapshot)).slice(0, 30).map(a => { const s = a.snapshot || {}; const card = (s.cards && s.cards[0]) || {}; const body = (s.body && (s.body.text || (s.body.markup && s.body.markup.__html))) || card.body || a.adText || ''; const plats = a.publisherPlatform || a.publisher_platform || []; return { page: a.pageName || a.page_name || s.page_name || '', title: s.title || card.title || '', text: String(body).replace(/<[^>]+>/g, '').slice(0, 250), cta: s.cta_text || card.cta_text || '', start: a.startDateFormatted || a.start_date || '', platforms: Array.isArray(plats) ? plats.join(', ') : String(plats), link: a.adArchiveID ? 'https://www.facebook.com/ads/library/?id=' + a.adArchiveID : (a.url || '') }; });
const newsDigest = newsItems.map(n => '- ' + n.title + ' (' + n.date + ') ' + n.link).join('\n') || 'No recent news items were fetched.';
const socialDigest = socialItems.map(s => '- [' + s.source + '] ' + s.title + ' (' + s.engagement + ') ' + s.link).join('\n') || 'No Reddit/HN posts were fetched.';
const tiktokDigest = tiktokVideos.map(v => '- ' + v.views + ' views, ' + v.likes + ' likes, ' + v.shares + ' shares | @' + v.author + ' | ' + v.text + ' | ' + v.hashtags.map(x => '#' + x).join(' ') + ' | ' + v.date).join('\n') || 'No TikTok data was fetched.';
const tiktokCommentsDigest = tiktokComments.map(c => '- (' + c.likes + ' likes) ' + c.text).join('\n') || 'No TikTok comments were fetched.';
const fbPostsDigest = fbPosts.map(p => '- [' + p.page + '] ' + p.text + ' (' + p.likes + ' reactions, ' + p.comments + ' comments, ' + p.shares + ' shares) ' + p.date).join('\n') || 'No Facebook page posts were fetched.';
const fbAdsDigest = fbAds.map(a => '- [' + a.page + '] ' + (a.title ? a.title + ' - ' : '') + a.text + (a.cta ? ' | CTA: ' + a.cta : '') + (a.start ? ' | running since ' + a.start : '')).join('\n') || 'No Facebook ads were fetched.';
const businessContext = 'Company/Product: ' + input.company + '\nIndustry/Market: ' + input.industry + '\nRegion: ' + input.region + '\nKnown competitors: ' + input.competitors + '\nTarget customers: ' + input.target_customers + '\nSpecific focus: ' + input.focus + '\nToday: ' + $now.toFormat('yyyy-MM-dd');
