rder-radius:3px;background:var(--good);margin-top:2px}.bars i.e{background:var(--bad)}a{color:var(--acc)}pre{white-space:pre-wrap;font-size:12px;background:var(--bg);padding:10px;border-radius:8px}.src{font-size:13px}';
